<script setup lang="ts">
import {ref,reactive,onMounted,computed,watch} from 'vue'
import {api,message,notify,type Work} from '../api'
const props=defineProps<{collectionId?:number}>()
const emit=defineEmits<{saved:[number];busy:[boolean]}>()
const works=ref<Work[]>([]),ready=ref(false),busy=ref(false),error=ref(''),candidate=ref(''),dirty=ref(false)
const form=reactive({title:'',description:'',kind:'连载',published:false,workIds:[] as number[]})
watch(form,()=>{if(ready.value)dirty.value=true},{deep:true,flush:'sync'})
const available=computed(()=>works.value.filter(w=>!form.workIds.includes(w.id)&&(!w.collectionId||w.collectionId===props.collectionId)))
function title(id:number){return works.value.find(w=>w.id===id)?.title||'未命名稿件'}
function add(){const id=Number(candidate.value);if(id&&available.value.some(w=>w.id===id)){form.workIds.push(id);candidate.value=''}}
function move(i:number,delta:number){const ids=[...form.workIds];[ids[i],ids[i+delta]]=[ids[i+delta]!,ids[i]!];form.workIds=ids}
async function save(){if(busy.value)return;if([...form.title.trim()].length>25){error.value='合集名称最多 25 个字符';return}busy.value=true;error.value='';try{const r=props.collectionId?await api.put(`/member/collections/${props.collectionId}`,form):await api.post('/member/collections',form);dirty.value=false;notify('合集已保存');emit('saved',r.data.id)}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(async()=>{try{works.value=(await api.get('/member/works')).data;if(props.collectionId){const c=(await api.get(`/public/collections/${props.collectionId}`)).data;Object.assign(form,{title:c.title,description:c.description,kind:c.kind,published:c.published,workIds:c.works.map((w:Work)=>w.id)})}ready.value=true}catch(e){error.value=message(e)}})
watch(busy,value=>emit('busy',value))
defineExpose({canClose:()=>!dirty.value||confirm('合集修改尚未保存，确定关闭？')})
</script>
<template><div class="collection-editor-form"><h3>{{props.collectionId?'编辑合集':'新建合集'}}</h3><p v-if="error" role="alert" class="error-message">{{error}}</p><form v-if="ready" @submit.prevent="save"><fieldset :disabled="busy" class="collection-form-fields"><div class="panel"><label>合集名称<input v-model="form.title" required aria-describedby="collection-title-help"/></label><small id="collection-title-help" class="quiet-note">最多 25 个字符</small><label>类型<select v-model="form.kind"><option>连载</option><option>诗集</option><option>选集</option></select></label><label>简介<textarea v-model="form.description" rows="3" maxlength="1000"></textarea></label><label class="checkbox-label"><input type="checkbox" v-model="form.published"/>公开合集</label><p class="quiet-note">每篇文章只能归属一部合集。这里只能添加未加入其他合集的自有稿件，最多 500 篇；未发布篇目仅自己可见。</p></div><div class="section-heading"><h2>篇目顺序</h2></div><div class="collection-add"><select v-model="candidate" aria-label="选择稿件"><option value="">选择稿件</option><option v-for="w in available" :key="w.id" :value="w.id">{{w.title||'未命名稿件'}}{{w.status==='PUBLISHED'?'':'（未公开）'}}</option></select><button type="button" class="button secondary" :disabled="!candidate||form.workIds.length>=500" @click="add">添加</button></div><ol class="collection-contents editable"><li v-for="(id,i) in form.workIds" :key="id"><span>{{i+1}}</span><strong>{{title(id)}}</strong><div class="collection-order"><button type="button" :disabled="i===0" :aria-label="`上移第${i+1}篇`" @click="move(i,-1)">上移</button><button type="button" :disabled="i===form.workIds.length-1" :aria-label="`下移第${i+1}篇`" @click="move(i,1)">下移</button><button type="button" :aria-label="`移除第${i+1}篇`" @click="form.workIds.splice(i,1)">移除</button></div></li></ol><p v-if="!form.workIds.length" class="quiet-note">尚未添加篇目</p><button class="button" :disabled="busy">{{busy?'保存中…':'保存合集'}}</button></fieldset></form><p v-else-if="!error" role="status">正在载入…</p></div></template>

<style scoped>.collection-form-fields{border:0;padding:0;margin:0;min-width:0}.collection-editor-form h3{font-size:16px;margin:0 0 18px}.collection-editor-form .panel{background:transparent}.collection-editor-form label{margin-bottom:16px}</style>
